-- Dansk portion 2 del 2/3: 167 MC-spørgsmål på sværhedsskalaen 1-10.000, niveau 3333-6563.
-- Del af de 5.000 nye danskopgaver. Skrevet fra bunden til dansk folkeskole, 3.-9. klasse.
-- Genereret af tools/questions/build-danish-5000.mjs; ret i tools/questions/fixtures/danish-5000/, ikke her.
-- Kræver migration A (20261020120000_difficulty_scale_a): kolonnen questions.difficulty_level.
--
-- Niveau: hver opgave har et eksplicit difficulty_level (forfatterens skøn, ikke en måling).
-- target_grade/difficulty_band er afledt baglæns af niveauet (cellen i §4.1).
--
-- INAKTIV VED INDSÆTTELSEN: alle rækker får is_active=false og metadata.level_batch='danish2'.
-- Aktivering er en SEPARAT migration efter dokumenteret stikprøvekontrol og særskilt ejergodkendelse.
-- Må KUN anvendes via apply_migration med særskilt ejer-autorisation (D-110).

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band, difficulty_level)
SELECT
  jsonb_build_object('question', e->>'q', 'options', e->'o', 'correct', e->>'a',
                     'accepted_answers', jsonb_build_array(e->>'a'), 'review_text', e->>'r'),
  'mc', 'short',
  jsonb_build_object('concepts', jsonb_build_array(m.concept), 'cognitive_skill', m.skill,
                     'difficulty_type', m.dtype, 'misconception_type', m.mis,
                     'challenge_role', e->>'role', 'insight_type', e->>'insight',
                     'practice_variant', e->>'variant',
                     'level_batch', 'danish2', 'domain', 'danish'),
  'mc_single', (e->>'b')::int, 'auto', false, 'danish', (e->>'g')::int,
  (e->>'b')::int, (e->>'l')::int
FROM jsonb_array_elements($$[
{"l":3333,"g":5,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Det er Noahs egen taske. Hvilket ord passer: 'Noah pakker ___ taske.'","o":["hans","sit","sine","sin"],"a":"sin","r":"Tasken tilhører grundleddet Noah, så der skal stå 'sin'. 'Hans' ville betyde en anden drengs taske."},
{"l":3355,"g":5,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Hvad er stavet rigtigt? 'Vi føler os ___ i vores nye klasse.'","o":["trygge","tryge","trykke","tryke"],"a":"trygge","r":"Grundformen er 'tryg'. Y'et er kort, så g'et fordobles, når ordet får -e i flertal."},
{"l":3377,"g":5,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Find hensynsleddet: 'Farfar gav Asta en nøgle.'","o":["Farfar","Asta","en nøgle","gav"],"a":"Asta","r":"Spørg: Hvem fik nøglen? Det gjorde Asta, så hun er hensynsled. 'En nøgle' er det, der blev givet, altså genstandsleddet."},
{"l":3397,"g":5,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Hvorfor skal der komma i: 'Fordi Ida var syg, blev hun hjemme.'?","o":["Fordi der er en opremsning","Fordi nogen taler direkte","Fordi ledsætningen står først","Fordi sætningen spørger om noget"],"a":"Fordi ledsætningen står først","r":"'Fordi Ida var syg' er en ledsætning. Når den står foran hovedsætningen, skal der komma efter den."},
{"l":3415,"g":5,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvilket ord mangler: 'Fiskeren sad stille i timevis og ventede på et bid. Han var meget ___.'","o":["utålelig","forhastet","rastløs","tålmodig"],"a":"tålmodig","r":"Den tålmodige kan vente roligt. Rastløs betyder det modsatte: at man ikke kan sidde stille."},
{"l":3435,"g":5,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Et af ordene skal have stort bogstav, også midt i en sætning. Hvilket?","o":["Sverige","Tirsdag","Svensk","Juni"],"a":"Sverige","r":"Sverige er et land og dermed et navn. Ugedage, sprog og måneder skrives med lille inde i en sætning."},
{"l":3454,"g":5,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Find den rigtige form: 'Min vej til skole er ___ end din.'","o":["længrere","længere","lengere","længgere"],"a":"længere","r":"Det er højere grad af 'lang'. Ordet har æ og ng, og det ender på -ere."},
{"l":3475,"g":5,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvilket af disse dyr er et 'krybdyr'?","o":["frø","salamander","firben","muldvarp"],"a":"firben","r":"Krybdyr som firben og slanger har skæl og tør hud. Frøer og salamandre er padder, og muldvarpen er et pattedyr."},
{"l":3495,"g":5,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Antallet af harer i Danmark er faldet. En af grundene er, at markerne er blevet større, og at der er færre hegn og små krat. Her skjulte harerne sig før. Nu er der mange steder, hvor de ikke kan gemme sig for ræve og rovfugle.' Hvad kan man slutte om hegn?","o":["De gør det lettere for ræve at fange harer om vinteren","De gør markerne større for landmænd","De er med til at fjerne rovfugle helt","De kan hjælpe harer med at overleve"],"a":"De kan hjælpe harer med at overleve","r":"Færre hegn betyder færre gemmesteder. Hegn beskytter altså harerne."},
{"l":3512,"g":5,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Vælg det rigtige ord: 'Influenzaen bredte sig hurtigt fra klasse til klasse på skolen. Det var en lille ___.'","o":["epidemi","allergi","vaccine","diagnose"],"a":"epidemi","r":"En epidemi er en smitsom sygdom, der hurtigt rammer mange mennesker. Her smittede influenzaen fra klasse til klasse."},
{"l":3531,"g":5,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Lukas flyttede altid sine brikker, så snart det blev hans tur. Farfar tænkte længe, før han flyttede, og han vandt hver gang. En dag satte Lukas sig på hænderne og kiggede på brættet i et helt minut, før han rørte en brik. Det spil varede meget længere, og for første gang vandt han.' Hvad har Lukas lært?","o":["At farfar lader ham vinde, når han flytter langsomt","At det hjælper at tænke sig om, før man flytter","At man skal flytte så hurtigt som muligt","At skak er bedst, når spillet varer længe"],"a":"At det hjælper at tænke sig om, før man flytter","r":"Så længe han flyttede med det samme, tabte han. Da han kiggede på brættet først, ligesom farfar, vandt han."},
{"l":3553,"g":5,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Hvad er rigtigt? 'Træets ___ går dybt ned i jorden.'","o":["røder","roder","rødder","rødre"],"a":"rødder","r":"Ental er 'rod'. I flertal skifter o til ø, og d'et fordobles."},
{"l":3575,"g":5,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvilket ord passer: 'Elias glæder ___ til sommerferien.'","o":["ham","han","hans","sig"],"a":"sig","r":"Det hedder 'at glæde sig'. 'Sig' peger tilbage på Elias selv, mens 'ham' ville være en anden dreng."},
{"l":3594,"g":5,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Kære redaktion. Jeg er træt af, at folk parkerer deres løbehjul midt på fortovet. Min farmor bruger rollator, og i går måtte hun gå ud på vejen for at komme forbi. Det er farligt! Kan vi ikke få faste steder til løbehjulene? Venlig hilsen Freja, 12 år' Hvilken type tekst er det?","o":["Et læserbrev","En nyhed","Et referat","En dagbog"],"a":"Et læserbrev","r":"Freja skriver til en avis, fortæller sin holdning og beder om en løsning. Det er kendetegn for et læserbrev."},
{"l":3610,"g":5,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"f","variant":"authored","q":"Hvad hedder det, når to linjer lige efter hinanden rimer?","o":["krydsrim","parrim","omfavnende rim","bogstavrim"],"a":"parrim","r":"Ved parrim rimer linjerne to og to, altså linje 1 på 2 og linje 3 på 4. Ved krydsrim skifter rimene."},
{"l":3630,"g":5,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Hvad skal der stå? 'Jeg har to ___ og en lillebror.'","o":["søstere","søstrer","søstre","søsterer"],"a":"søstre","r":"Ental er 'søster'. I flertal falder e'et væk, så ordet ender på -stre."},
{"l":3650,"g":5,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"f","variant":"authored","q":"Læs: 'Søde Signe sidder stille.' Hvad kaldes det, at flere ord begynder med den samme lyd?","o":["enderim","krydsrim","parrim","bogstavrim"],"a":"bogstavrim","r":"Bogstavrim står i begyndelsen af ordene. Enderim, krydsrim og parrim handler om slutningen af ordene."},
{"l":3670,"g":5,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad betyder 'sandsynligt' i sætningen: 'Det er sandsynligt, at det regner i morgen.'","o":["Det vil nok ske","Det er helt sikkert","Det kan aldrig ske","Det er allerede sket"],"a":"Det vil nok ske","r":"Noget sandsynligt er ikke sikkert, men der er god grund til at tro, at det sker."},
{"l":3692,"g":5,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvilket ord har næsten samme betydning som 'omhyggeligt' her: 'Hun tegnede kortet omhyggeligt.'","o":["sjusket","grundigt","lydløst","hastigt"],"a":"grundigt","r":"Den, der gør noget omhyggeligt, tager sig tid og passer på hver eneste detalje. Sjusket er det stik modsatte."},
{"l":3707,"g":5,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Hvilken form skal stå på stregen? 'Efter maden ___ vi bordet.'","o":["rydede","ryddet","ryddede","rydte"],"a":"ryddede","r":"Ordet har dobbelt d i stammen og -ede i datid, så der er tre d'er i alt."},
{"l":3729,"g":5,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Sæt ind: 'Butikken ___ allerede klokken seks i går.'","o":["lukede","lukket","lukkte","lukkede"],"a":"lukkede","r":"Dobbelt k, fordi u'et er kort. Sætningen står i datid, så ordet ender på -ede."},
{"l":3751,"g":5,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Hvad skal der stå? 'I nat ___ jeg om en lilla drage.'","o":["drømte","drømmede","drømmte","drømde"],"a":"drømte","r":"Datid ender her på -te, og foran t står der kun ét m."},
{"l":3772,"g":5,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Du kan nemt spare på vandet. Tag kortere bade, og sluk for hanen, mens du børster tænder. Et bad på ti minutter bruger mere end 100 liter vand. Hvis alle i din familie skærer fem minutter af badet, sparer I mange tusinde liter om året.' Hvad vil teksten have dig til?","o":["At vaske sig mindre grundigt hver dag","At tage kortere bade og spare på vandet","At slukke for hanen, når man er i bad","At regne ud, hvor meget vand der er i et bad"],"a":"At tage kortere bade og spare på vandet","r":"Teksten giver gode råd og tal, så du får lyst til at bruge mindre vand."},
{"l":3790,"g":5,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Danmarks mange vindmøller laver strøm af vinden. Vinden får vingerne til at dreje, og det får en generator til at lave elektricitet. Når det ikke blæser, må strømmen komme andre steder fra. Derfor er det svært at klare sig med vindkraft alene.' Hvad er problemet med vindkraft ifølge teksten?","o":["Møllerne skal have strøm for at kunne dreje","Vingerne drejer alt for hurtigt","Vinden blæser ikke hele tiden","Generatoren laver kun strøm om natten"],"a":"Vinden blæser ikke hele tiden","r":"Teksten nævner, at strømmen må komme andre steder fra, når det ikke blæser. Det er problemet."},
{"l":3808,"g":5,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Hvis du har en plante i vindueskarmen, vil den vende sig mod lyset. Årsagen er et stof i planten, som samler sig på skyggesiden. Her vokser cellerne hurtigere, så stænglen bøjer sig mod vinduet.' Hvorfor bøjer planten sig ifølge teksten?","o":["Fordi lyset trækker i bladene","Fordi vinduet er varmere end stuen","Fordi cellerne på lyssiden vokser hurtigst","Fordi skyggesiden vokser hurtigere"],"a":"Fordi skyggesiden vokser hurtigere","r":"Når cellerne på skyggesiden vokser mest, bliver den side længere, og stænglen bøjer sig mod lyset."},
{"l":3828,"g":5,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Bøgerne tilhører Alma. Hvilket ord passer: 'Alma pakker ___ bøger ned i tasken.'","o":["sine","sin","sit","hendes"],"a":"sine","r":"Bøgerne tilhører grundleddet, og de er flere, så der skal stå flertalsformen 'sine'."},
{"l":3850,"g":5,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvilket udsagnsled giver førnutid: 'Gæsterne ___ til festen.'","o":["kom","er kommet","var kommet","kommer"],"a":"er kommet","r":"Førnutid dannes med 'har' eller 'er' i nutid plus tillægsform. 'Var kommet' er førdatid."},
{"l":3871,"g":5,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Asger stod med fiskestangen og kiggede på flåddet. Morfar sagde, at man ikke skulle fiske efter fisk, men efter ro. Asger forstod det ikke. Men da solen stod op over søen, og han ikke havde fået bid i to timer, bemærkede han, at han slet ikke var irriteret.' Hvad mener morfar med at fiske efter ro?","o":["At man kun må fange fisk, der er rolige","At man skal være stille for at fange noget","At det vigtigste er at falde til ro og nyde det","At fisk kun bider, når vandet slet ikke bevæger sig"],"a":"At det vigtigste er at falde til ro og nyde det","r":"Asger får ingen fisk, men er alligevel ikke irriteret. Det viser, hvad morfar mente: Det gode ved turen er roen."},
{"l":3889,"g":5,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'På bibliotekets opslagstavle stod der: Bytteklubben for brætspil mødes hver anden torsdag. Medbring et spil, du er træt af, og gå hjem med et andet. Ingen penge, kun gode spil. Spil med manglende brikker tager vi ikke imod.' Hvad må man IKKE tage med til klubben?","o":["Et spil, man er træt af","Et nyt spil til at bytte med","Et spil til mange spillere","Et spil, der mangler brikker"],"a":"Et spil, der mangler brikker","r":"Sidste sætning siger, at klubben ikke tager imod spil med manglende brikker."},
{"l":3905,"g":5,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvilken form af 'at tælle' passer: 'Vi har ___ alle kuglerne i glasset.'","o":["talt","talte","tæller","tælle"],"a":"talt","r":"Tillægsformen af 'at tælle' er 'talt', og den står efter 'har'. 'Talte' er datid."},
{"l":3927,"g":5,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Vælg den rigtige form af 'at koge': 'Et ___ æg lå på tallerkenen.'","o":["kogte","kogt","koger","koge"],"a":"kogt","r":"Efter 'et' står ubestemt form, så det hedder 'kogt'. 'Kogte' bruges efter 'det' eller i flertal."},
{"l":3947,"g":5,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad vil ordsproget 'Alt er ikke guld, der glimrer' lære os?","o":["Guld er ikke længere så meget værd som i gamle dage","Det er bedre at have sølv end at have guld","Noget, der ser flot ud, behøver ikke at være godt","Man skal altid rense sine smykker grundigt"],"a":"Noget, der ser flot ud, behøver ikke at være godt","r":"Noget kan skinne som guld uden at være det. Ordsproget advarer mod at lade sig narre af en flot overflade."},
{"l":3967,"g":5,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Hvilken tekst om festen har punktum og komma de rigtige steder?","o":["Da festen var slut. Gik vi hjem, næste dag sov vi længe.","Da festen var, slut gik vi hjem. Næste dag sov vi længe.","Da festen var slut gik vi hjem, næste dag. Sov vi længe.","Da festen var slut, gik vi hjem. Næste dag sov vi længe."],"a":"Da festen var slut, gik vi hjem. Næste dag sov vi længe.","r":"Ledsætningen 'Da festen var slut' kan ikke stå alene og skal efterfølges af komma. Punktummet kommer, når hele sætningen er færdig."},
{"l":3985,"g":5,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"f","variant":"authored","q":"Hvad forstår man ved miljøet i en fortælling?","o":["Det sted og den tid, historien foregår i","De ord, personerne siger til hinanden","De følelser, hovedpersonen har til sidst","Den måde, teksten er sat op på siden"],"a":"Det sted og den tid, historien foregår i","r":"Miljøet er der, hvor og hvornår historien foregår. Det kan være en lille by i dag eller et slot for længe siden."},
{"l":4007,"g":5,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Vælg det rigtige ord: 'Dommeren må ikke holde med nogen af holdene. Hun skal være ___.'","o":["loyal","neutral","streng","nervøs"],"a":"neutral","r":"Den, der er neutral, tager ikke parti for nogen. Loyal passer ikke, fordi den loyale holder med sin egen side."},
{"l":4026,"g":5,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvilken fortsættelse er rigtig: 'Når klokken ringer, ...'","o":["eleverne går ind.","eleverne ind går.","går eleverne ind.","ind eleverne går."],"a":"går eleverne ind.","r":"Når sætningen begynder med en ledsætning, står udsagnsleddet før grundleddet bagefter: først 'går', så 'eleverne'."},
{"l":4048,"g":5,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Hvilken stavning er rigtig? 'Computeren ___ ikke i dag.'","o":["fungere","fungeret","funkerer","fungerer"],"a":"fungerer","r":"Nutid af ord på -ere ender på -erer. Ordet staves med g."},
{"l":4068,"g":5,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Store mængder sne reflekterer solens lys og varme. Når sneen smelter, kommer den mørke jord eller det mørke hav frem, og det opsuger mere varme. Så smelter sneen omkring endnu hurtigere. Sådan kan der opstå en proces, der forstærker sig selv.' Hvad betyder det, at processen forstærker sig selv?","o":["At jo mere sne der smelter, jo hurtigere smelter resten","At sne reflekterer lyset bedre, jo mere den smelter","At havet til sidst bliver helt mørkt om sommeren","At solen bliver stærkere, når der kommer mere sne"],"a":"At jo mere sne der smelter, jo hurtigere smelter resten","r":"Når sneen smelter, kommer der mørk jord frem, som bliver varm. Så smelter sneen omkring endnu hurtigere."},
{"l":4086,"g":5,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Hver søndag spiste de frokost hos farmor, og hver søndag sad far og kiggede på sit ur. På vej hjem sagde far altid, at det var et spild af tid. Men da farmor blev syg, var det far, der kørte derhen hver dag efter arbejde. Ingen bad ham om det.' Hvad viser teksten om far?","o":["At han er helt ligeglad med, hvordan farmor har det","At han holder mere af farmor, end han viser","At han passer sit arbejde dårligt","At han er tvunget til at køre derhen"],"a":"At han holder mere af farmor, end han viser","r":"Hans ord siger ét, men hans handling, da det gælder, viser noget andet. Der står, at ingen bad ham om det."},
{"l":4105,"g":5,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad kaldes det, når dyr flytter sig over store afstande med årstiderne?","o":["metamorfose","dvale","migration","fældning"],"a":"migration","r":"Trækfugle migrerer hvert år mellem steder med mad. Migration betyder at flytte sig fra et sted til et andet."},
{"l":4125,"g":5,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Sæt det rigtige ord ind: 'Toget holder ved næste ___.'","o":["stasion","stasjon","statjon","station"],"a":"station","r":"Ordet ender på -tion, selvom man siger 'sjon'."},
{"l":4147,"g":5,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Vælg stavemåden: 'Må jeg få en stor ___ is?'","o":["portion","porsjon","porsion","portjon"],"a":"portion","r":"Ordet er et lånord med endelsen -tion. Sj-lyden skrives med t."},
{"l":4167,"g":5,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Hvert forår kommer storkene tilbage til reden på Præstegårdsvej. Men i år kom kun den ene. Den stod på reden i ugevis og klaprede med næbbet, og folk stoppede op for at se til den. En morgen i maj var reden tom. Tilbage lå kun lidt græs og den rene, blå himmel.' Hvad tænker folk nok på, når de stopper op?","o":["At storken larmer for meget med næbbet","At det er trist, at storken er alene","At storken er ved at bygge reden om","At storken snart skal flyve sydpå"],"a":"At det er trist, at storken er alene","r":"Storken står alene på reden, og folk stopper op for at se til den. De har ondt af den, selvom teksten ikke siger det direkte."},
{"l":4185,"g":5,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Havets niveau stiger og falder to gange i døgnet. Det kaldes tidevand. Det skyldes først og fremmest månens tiltrækningskraft, som trækker i vandet. I Vadehavet kan man ved lavvande gå ud på havbunden, men man skal kende tidspunkterne, for vandet kommer hurtigt tilbage.' Hvorfor skal man kende tidspunkterne i Vadehavet?","o":["For at se månen stå op over vandet","For at finde bestemte fisk på bunden","For at nå hjem, inden vandet stiger","For at kunne bade, mens vandet er højest"],"a":"For at nå hjem, inden vandet stiger","r":"Faren er, at vandet kommer hurtigt tilbage. Man skal derfor vide, hvornår man skal vende om."},
{"l":4202,"g":5,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Sæt ind: 'Med den rigtige ___ kan du kaste bolden meget længere.'","o":["tekknik","teknikk","tegnik","teknik"],"a":"teknik","r":"Lånord på -ik skrives med ét k til sidst, og der er også kun ét k inde i ordet."},
{"l":4224,"g":5,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvilket ord er et biord: 'Bamsen ligger nede i kælderen.'","o":["nede","ligger","i","kælderen"],"a":"nede","r":"'Nede' fortæller, hvor bamsen er, og kan stå uden et navneord efter sig. 'I' er forholdsordet i sætningen."},
{"l":4246,"g":5,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvad er genstandsleddet: 'Den film har jeg set tre gange.'","o":["jeg","Den film","har set","tre gange"],"a":"Den film","r":"Spørg: Hvad har jeg set? Genstandsleddet står forrest for at blive fremhævet."},
{"l":4266,"g":5,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Da toget kørte, åbnede Hamid sin blå taske for at finde sin bog. Der lå en fodboldtrøje og et par støvler i den. Han havde aldrig spillet fodbold. På sædet over for ham sad en dreng med samme slags taske og kiggede forvirret ned på Hamids matematikbog. De så på hinanden og begyndte at grine.' Hvad er der nok sket?","o":["Drengen har taget Hamids bog for at drille","Hamid har fået nye ting af sin træner","De to drenge har byttet tasker ved en fejl","Hamid har glemt sin egen taske derhjemme"],"a":"De to drenge har byttet tasker ved en fejl","r":"De har samme slags taske, og hver af dem sidder med den andens ting. Når de griner, er det, fordi de begge opdager fejlen."},
{"l":4288,"g":6,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad betyder 'fornemmelse' i sætningen 'Jeg har en fornemmelse af, at det bliver regnvejr'?","o":["en viden, man har fået fra en bog i skolen","et løfte, man har fået af nogen","en plan, man har lavet i forvejen","en følelse, man ikke helt kan forklare"],"a":"en følelse, man ikke helt kan forklare","r":"En fornemmelse er noget, man mærker eller aner, uden at man kan bevise det."},
{"l":4309,"g":6,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Hvilken sætning har rigtige kommaer i opremsningen af frugt?","o":["Vi købte æbler, pærer, blommer og kirsebær.","Vi købte æbler, pærer, blommer, og kirsebær.","Vi købte, æbler, pærer, blommer og kirsebær.","Vi købte æbler pærer, blommer og kirsebær."],"a":"Vi købte æbler, pærer, blommer og kirsebær.","r":"I en opremsning står der komma mellem delene, men ikke foran det sidste 'og'."},
{"l":4325,"g":6,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Avisen skriver, at et gammelt band gør 'comeback'. Hvad betyder det?","o":["bandet stopper for altid efter denne turné","bandet vender tilbage efter en lang pause","bandet har skiftet alle sine medlemmer ud","bandet spiller sin allerførste koncert"],"a":"bandet vender tilbage efter en lang pause","r":"'Comeback' er lånt fra engelsk og betyder en tilbagevenden, især for en kunstner eller sportsudøver."},
{"l":4346,"g":6,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Hvad skal der stå på stregen? 'Menneskets ___ består af over 200 knogler.'","o":["skællet","skellet","skelet","skelett"],"a":"skelet","r":"Ordet har ét l og ét t. Med dobbelt l ville det betyde grænsen mellem to grunde."},
{"l":4366,"g":6,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvilket ord er et adjektiv: 'Gulerødderne fra haven er sprøde.'","o":["Gulerødderne","haven","er","sprøde"],"a":"sprøde","r":"Adjektiv er det latinske navn for tillægsord. 'Sprøde' beskriver gulerødderne."},
{"l":4385,"g":6,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"I nyhederne hører vi, at buschaufførerne er gået i 'strejke'. Hvad betyder det?","o":["de nægter at arbejde for at få noget ændret","de er taget på ferie sammen med kollegerne","de har fået nye uniformer af firmaet","de kører en anden rute end normalt"],"a":"de nægter at arbejde for at få noget ændret","r":"Ved en strejke lægger de ansatte arbejdet ned i fællesskab, ofte for at få bedre løn eller vilkår."},
{"l":4404,"g":6,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Hvilken sætning bruger forkortelsen af 'for eksempel' rigtigt?","o":["Tag f.eks en banan med.","Tag f.eks. en banan med.","Tag feks. en banan med.","Tag fe.ks. en banan med."],"a":"Tag f.eks. en banan med.","r":"Forkortelsen består af f for 'for' og eks for 'eksempel', og hver del får et punktum: f.eks."},
{"l":4423,"g":6,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad betyder 'fler-' i ordene 'flersproget', 'flerfarvet' og 'flerårig'?","o":["kun én","næsten ingen","mere end én","helt ens"],"a":"mere end én","r":"'Fler-' hænger sammen med 'flere'. Et flersproget barn taler altså to eller flere sprog."},
{"l":4442,"g":6,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Personen, der styrer et skib, er skibets ___. Hvilket ord er stavet rigtigt?","o":["kaptain","kabtajn","kapten","kaptajn"],"a":"kaptajn","r":"Ordet skrives med j og slutter på -tajn. Det er p, ikke b, før t."},
{"l":4462,"g":6,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"f","variant":"authored","q":"Hvordan bredte folkeeventyrene sig i gamle dage?","o":["De blev fortalt fra mund til mund","De blev trykt i aviserne hver uge","De blev læst op af skolebøgerne","De blev skrevet ind i salmebøgerne"],"a":"De blev fortalt fra mund til mund","r":"Folkeeventyr blev fortalt mundtligt fra generation til generation. Først senere blev de skrevet ned."},
{"l":4483,"g":6,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvilket ord passer i sætningen? 'Det var en ___ beslutning: Hun tænkte sig grundigt om, før hun valgte.'","o":["forhastet","velovervejet","tilfældig","ubetænksom"],"a":"velovervejet","r":"Noget velovervejet er tænkt godt igennem. De tre andre ord beskriver det modsatte af at tænke sig grundigt om."},
{"l":4500,"g":6,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Vi plejer at sige, at dyr ikke kan lyve. Men nogle fugle kan. Drongoen, en fugl i det sydlige Afrika, kan efterligne andre fugles advarselsskrig. Når de andre flygter, spiser drongoen den mad, de har ladt ligge. Det er ikke en sjov leg for de andre fugle.' Hvorfor bruger forfatteren ordet lyve om fuglen?","o":["Fordi den har lært at tale med mennesker","Fordi den skriger højere end de andre fugle","Fordi den narrer de andre med falsk alarm","Fordi den efterligner andre fugle for sjov"],"a":"Fordi den narrer de andre med falsk alarm","r":"Drongoen sender en falsk advarsel for at få maden. Forfatteren sammenligner det med at lyve."},
{"l":4520,"g":6,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Katten Molly har ansat hele familien. Far åbner døren, når hun sætter sig foran den. Jeg fylder skålen, så snart hun kigger på den. Vi får ingen løn, men hun ser på os, som om vi burde sige tak.' Hvordan skal ordet 'ansat' forstås?","o":["Som en klage over, at katten giver alt for meget arbejde","Som en forklaring på, at børnene får lommepenge for katten","Som et tegn på, at familien har lært katten at adlyde","Som en spøg med, hvem der bestemmer derhjemme"],"a":"Som en spøg med, hvem der bestemmer derhjemme","r":"Fortælleren leger med, at katten er chef, og at familien adlyder den. Det kan ligne en klage, men tonen er munter, og ingen ærgrer sig i teksten."},
{"l":4540,"g":6,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Kære Jonas. Jeg har overvejet dit forslag om at købe en hest til klassen. Det er en spændende tanke. Skolen har ganske vist ingen stald, intet græs og ingen penge, men jeg kan se, at du har tænkt dig om. Jeg foreslår, at vi starter med en guldfisk. Venlig hilsen din skoleleder' Hvordan svarer skolelederen?","o":["Med et venligt og sjovt nej","Med et ja til en hest, hvis der kommer penge","Med et vredt nej og en straf til Jonas","Med en plan for at bygge en stald snart"],"a":"Med et venligt og sjovt nej","r":"Skolelederen siger nej uden at sige det direkte. Guldfisken gør afslaget venligt og lidt sjovt."},
{"l":4560,"g":6,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Vores guide stoppede og sænkede stemmen. Han pegede ikke, men vi fulgte hans blik hen over mosen. Noget brunt bevægede sig i sivene. Da Yusuf hviskede, om det bare var en ko, rystede guiden på hovedet, smilede og lagde en finger på læben.' Hvad kan man slutte om guiden?","o":["Han frygter, at dyret i sivene er farligt for gruppen","Han har set et dyr, han ikke vil skræmme væk","Han er irriteret over, at Yusuf snakker på turen","Han ved, at det er en ko, der er gået vild fra marken"],"a":"Han har set et dyr, han ikke vil skræmme væk","r":"Den lave stemme, smilet og fingeren på læben viser, at han vil have ro omkring et spændende dyr. Frygt er fristende, men smilet passer ikke til en guide, der er bange."},
{"l":4582,"g":6,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad betyder 'demonstration' i sætningen 'Tusindvis af mennesker deltog i en demonstration foran Christiansborg'?","o":["en fremvisning af, hvordan en maskine virker","et marked, hvor man kan købe lokale varer","en samling af folk, der viser, hvad de mener","en rundvisning for turister på et slot"],"a":"en samling af folk, der viser, hvad de mener","r":"Folk møder op med skilte, så politikerne kan se, at mange er enige om en sag. Ordet kan også betyde en fremvisning, men det passer ikke her."},
{"l":4600,"g":6,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Glas kan smeltes om og blive til nyt glas igen og igen uden at miste kvalitet. Papirfibrene bliver derimod kortere for hver runde, og efter et antal gange kan de ikke bruges mere.' Hvad kan man slutte?","o":["Papir er mere værd end glas ved genbrug","Glas og papir kan genbruges lige mange gange","Papir er nemmere at sortere end glas","Glas kan genbruges flere gange end papir"],"a":"Glas kan genbruges flere gange end papir","r":"Ordet 'derimod' stiller de to materialer op mod hinanden: Glas kan fortsætte, mens papir har en grænse. Værdi og sortering nævnes ikke."},
{"l":4615,"g":6,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Ellen var på vej hjem fra skole, da hun kom forbi en bod med brændte mandler. Duften slog imod hende, og hun var igen syv år. Hun kunne høre karrusellen i Tivoli og smage sukkervand. Hun blev stående og smilede. Så købte hun en pose til far, for han ville også huske den tur.' Hvad er det, der sker for Ellen?","o":["Duften får hende til at huske en tur i Tivoli","Hun bliver svimmel af duften fra boden","Hun bliver bange, fordi hun hører en karrusel","Hun finder ud af, at der er kommet tivoli i byen"],"a":"Duften får hende til at huske en tur i Tivoli","r":"Hun 'var igen syv år'. Duften får hende til at huske turen så tydeligt, at det føles, som om den sker nu."},
{"l":4634,"g":6,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad vil det sige at 'tage ansvar' for en fejl?","o":["at give en anden person skylden for fejlen","at stå ved fejlen og gøre noget for at rette den","at skjule fejlen, så ingen nogensinde opdager den","at glemme fejlen og gå videre med det samme"],"a":"at stå ved fejlen og gøre noget for at rette den","r":"Den, der tager ansvar, indrømmer sin del af sagen og forsøger at gøre tingene gode igen."},
{"l":4655,"g":6,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Hunde kan lugte mange tusinde gange bedre end mennesker. Derfor bruges de til at finde mennesker, der er forsvundet. Nogle hunde er også trænet til at finde skimmelsvamp bag væggene i huse. Hunden reagerer, længe før man selv kan se svampen.' Hvad er fordelen ved den sidste slags hund?","o":["At hunden selv kan fjerne svampen","At hunden finder den person, der er væk","At man når at fjerne svampen i tide","At man selv kan lugte svampen bagefter"],"a":"At man når at fjerne svampen i tide","r":"Hunden finder svampen tidligt. Man kan slutte, at man så får tid til at gøre noget, før skaden bliver stor."},
{"l":4675,"g":6,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Vores klasse har lavet en undersøgelse af skolens toiletpapir. Sidste år brugte vi 2.400 ruller. Hvis hver elev bruger lidt mindre, kan vi spare 300 ruller, og dermed også mange penge. Vi har derfor hængt små skilte op. Men måske er det ikke det vigtigste, vi kan gøre for klimaet.' Hvad synes forfatterne om deres eget projekt?","o":["De overdriver, hvor vigtigt projektet er","De mener, at projektet er helt uden nogen betydning","De synes, at det er for dyrt at gennemføre","De tror på det, men ved, at det er en lille ting"],"a":"De tror på det, men ved, at det er en lille ting","r":"De fortæller om projektet, men slutter med at sige, at det næppe er det vigtigste. De ved godt, at der er større ting at gøre."},
{"l":4695,"g":6,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Det hele startede med en løgn. Oscar sagde, at han kunne svømme. Så skulle han vise det på lejren. Derfor sagde han, at han havde ondt i ørerne. Så skulle han til sygeplejersken. Da hun ringede til hans mor, kom sandheden om svømningen også frem.' Hvad er budskabet?","o":["En løgn fører let til flere løgne","Man skal lære at svømme, før man tager på lejr","Man skal sige det til en voksen, når man har ondt","Man skal altid fortælle sin mor, hvor man er"],"a":"En løgn fører let til flere løgne","r":"Den første løgn kræver en ny, og til sidst kommer det hele frem. Historien viser, hvordan løgn vokser."},
{"l":4708,"g":6,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Omar stiller et spørgsmål ved middagsbordet. Hvilken sætning er rigtig?","o":["»Hvornår spiser vi«? spurgte Omar.","»Hvornår spiser vi?« spurgte Omar.","»Hvornår spiser vi? spurgte Omar.","»Hvornår spiser vi.« spurgte Omar?"],"a":"»Hvornår spiser vi?« spurgte Omar.","r":"Spørgsmålstegnet hører til replikken og står inden for anførselstegnene. Der skal ikke også komma bagefter."},
{"l":4729,"g":6,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvilken tid står det første udsagnsled i: 'Min tante var flyttet til Odense, da jeg blev født.'","o":["datid","førnutid","førdatid","nutid"],"a":"førdatid","r":"'Var' plus tillægsform er førdatid. Flytningen skete før det andet tidspunkt i fortiden."},
{"l":4748,"g":6,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"f","variant":"authored","q":"Hvad hedder de to brødre i Astrid Lindgrens 'Brødrene Løvehjerte'?","o":["Mattis og Birk","Hans og Peter","Anders og Lars","Jonatan og Karl"],"a":"Jonatan og Karl","r":"Bogen handler om Jonatan og lillebroren Karl, der kaldes Tvebak. De får mange eventyr i landet Nangijala."},
{"l":4769,"g":6,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad vil det sige at 'slå koldt vand i blodet'?","o":["at falde ned og tage det roligt","at blive pludselig bange for noget","at tage en kold dukkert om morgenen","at være hård og afvisende over for andre"],"a":"at falde ned og tage det roligt","r":"Den, der slår koldt vand i blodet, dæmper sin ophidselse og tager det roligt i stedet for at fare op."},
{"l":4790,"g":6,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Vælg den rigtige stavemåde: 'Naboen har ___ at passe vores kat i ferien.'","o":["tilbudet","tilbudt","tilbydt","tilbud"],"a":"tilbudt","r":"Efter 'har' ender ordet på -dt, og y bliver til u."},
{"l":4805,"g":6,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Tillykke til Nørrebyskolens skakhold, der blev nummer to ved DM i Horsens! Holdet har kun eksisteret i et år. Træner Jamal Nasser er naturligvis stolt, men han siger, at det vigtigste er sket uden for brættet: – De er blevet bedre til at tabe. Det er lige så vigtigt.' Hvad mener træneren med det sidste?","o":["At holdet tit taber, fordi det er nyt","At det er vigtigere at tabe end at vinde","At det er vigtigt at kunne tåle at tabe","At holdet kun er blevet dårligere på et år"],"a":"At det er vigtigt at kunne tåle at tabe","r":"Træneren siger, at holdet er blevet bedre til at tabe, og at det er lige så vigtigt som placeringen."},
{"l":4825,"g":6,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Naturgruppen i Vestbyen har fået ny formand. Efter ti år trækker Anni Pedersen sig. Den nye formand er 19-årige Ali Reza, som lover at få flere unge med. Anni Pedersen siger: – Jeg er glad for at give stafetten videre. Hun bliver i gruppen som almindeligt medlem.' Hvad betyder det at give stafetten videre?","o":["At holde op med at løbe stafetløb","At dele opgaven med en anden","At melde sig ud af gruppen","At lade en anden overtage opgaven"],"a":"At lade en anden overtage opgaven","r":"Det er et billede fra stafetløb: Når én løber er færdig, overtager den næste. Her overtager Ali Reza formandsposten."},
{"l":4844,"g":6,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"f","variant":"authored","q":"Hvad kaldes overskriften på en artikel i avisens fagsprog?","o":["en rubrik","en klumme","et tillæg","en billedtekst"],"a":"en rubrik","r":"Rubrikken er artiklens overskrift. Den skal fange læseren og sige kort, hvad artiklen handler om."},
{"l":4862,"g":6,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Kloge hoveder har beregnet, at vi får en bedre skole, hvis vi får færre timer. Andre kloge hoveder beregner det modsatte. Jeg har spurgt min lillebror. Han sagde, at det kommer an på, om man må spille bold. Det var i hvert fald det mest fornuftige, jeg har hørt i ugens løb.' Hvad er tonen i teksten?","o":["Højtidelig og alvorlig","Ironisk og let drillende","Vred og fornærmende","Begejstret og rosende"],"a":"Ironisk og let drillende","r":"Skribenten driller de kloge hoveder ved at sætte lillebrorens bemærkning over deres beregninger."},
{"l":4883,"g":6,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Find grundleddet i ledsætningen: 'Vi løb ind, fordi lynet slog ned.'","o":["Vi","fordi","lynet","ned"],"a":"lynet","r":"Ledsætningen er 'fordi lynet slog ned'. Spørg: Hvad slog ned? 'Vi' er grundled i hovedsætningen."},
{"l":4902,"g":6,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Spørger du en stavekontrol, er der intet galt med sætningen: Jeg købte en gave til min mor, og hun blev glad for den gave, som jeg købte til min mor. Den er korrekt stavet. Men alle kan se, at den er dårligt skrevet. Stavekontrollen ser kun på bogstaverne, ikke på meningen.' Hvad er tekstens hovedpointe?","o":["At stavekontrol er ubrugelig til alt, hvad man skriver","At sætninger helst skal være meget korte","At stavning er vigtigere end indhold","At du selv må læse det, du har skrevet, igennem"],"a":"At du selv må læse det, du har skrevet, igennem","r":"Eksemplet viser, at maskinen ikke ser det, læseren ser. Man må selv læse igennem."},
{"l":4922,"g":6,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Hvad er stavet rigtigt? 'Bogen har en flot ___ på hver side.'","o":["illustration","ilustration","illustrasjon","illustation"],"a":"illustration","r":"Ordet begynder med dobbelt l, og der er r efter t."},
{"l":4942,"g":6,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Forskerne satte to grupper af mus på forskellig kost i tolv uger. Den ene gruppe tog mere på end den anden. Men forskerne advarer mod at drage for store konklusioner: Mus er ikke mennesker. Resultatet giver snarere nye spørgsmål end sikre svar.' Hvad er forskernes holdning til resultatet?","o":["Det er helt sikkert, at det også gælder mennesker","Man skal passe på med at tro for meget på det","Det siger slet intet om noget som helst","Det viser, at kosten ikke betyder noget"],"a":"Man skal passe på med at tro for meget på det","r":"Forskerne advarer mod for store konklusioner. De afviser ikke resultatet, men de er forsigtige."},
{"l":4961,"g":6,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"f","variant":"authored","q":"Læs: 'Lise var modig og ærlig.' Hvordan bliver personen karakteriseret her?","o":["Indirekte, gennem det hun gør i teksten","Gennem det, de andre personer i teksten siger om hende","Direkte, fordi fortælleren siger, hvordan hun er","Gennem en samtale mellem hende og moren"],"a":"Direkte, fordi fortælleren siger, hvordan hun er","r":"Fortælleren siger ligeud, at Lise er modig og ærlig. Ved indirekte karakteristik må læseren selv slutte det ud fra handlinger."},
{"l":4982,"g":6,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvilket ord passer: 'Vi kunne se, at ___ kom løbende.'","o":["ham","hans","sig","han"],"a":"han","r":"Ordet er grundled i ledsætningen 'at han kom løbende'. Som grundled hedder det 'han'."},
{"l":5000,"g":6,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Mormor siger, at alt var bedre i gamle dage. Bagefter beder hun mig finde en video om strikning på sin telefon.' Hvad er det, teksten lægger mærke til?","o":["At hendes handling ikke passer med hendes ord","At hun mest kan lide at se film om gamle dage","At hun har strikket på den samme trøje længe","At hun ikke kan bruge telefonen til noget"],"a":"At hendes handling ikke passer med hendes ord","r":"Hun roser fortiden, men bruger glad nutidens teknik. Det er modsætningen, der er pointen."},
{"l":5015,"g":6,"b":3,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Vælg den rigtige form af 'at vide': 'Hvis jeg havde ___ det, var jeg kommet.'","o":["vidste","vidst","ved","vide"],"a":"vidst","r":"Efter 'havde' skal der stå tillægsform. 'Vidste' er datid, mens tillægsformen hedder 'vidst'."},
{"l":5033,"g":6,"b":3,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Hvad kalder Robinson Crusoe den mand, han møder på øen?","o":["Mandag","Lørdag","Fredag","Søndag"],"a":"Fredag","r":"Robinson møder ham på en fredag og giver ham navnet efter dagen. De bliver hinandens selskab på øen."},
{"l":5055,"g":6,"b":3,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad betyder det at 'forudsige' noget?","o":["at gentage, hvad der er sket","at sige noget forkert","at sige noget højt foran andre","at sige, hvad der vil ske"],"a":"at sige, hvad der vil ske","r":"'Forud' betyder på forhånd. Den, der forudsiger noget, siger det, før det sker, som i en vejrudsigt."},
{"l":5077,"g":6,"b":3,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad betyder det, at ens hårde arbejde 'bærer frugt'?","o":["at det giver et godt resultat","at det bliver alt for hårdt","at det bliver betalt med mad","at det skal gøres om igen"],"a":"at det giver et godt resultat","r":"Billedet kommer fra et træ, der giver frugt, når det er passet. I overført betydning er frugten resultatet."},
{"l":5092,"g":6,"b":3,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Vælg datid af 'at trække': 'Hesten ___ vognen op ad bakken i går.'","o":["trukket","trak","trækker","trække"],"a":"trak","r":"'At trække' skifter vokal: trækker, trak, har trukket."},
{"l":5114,"g":6,"b":3,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Vælg datid af 'at gribe': 'I lørdags ___ målmanden bolden i sidste sekund.'","o":["grebet","griber","greb","gribe"],"a":"greb","r":"'I lørdags' viser, at det er sket. Datid af 'at gribe' er 'greb'."},
{"l":5136,"g":6,"b":3,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Vælg datid af 'at nyde': 'I søndags ___ vi solen på terrassen.'","o":["nydt","nyder","nyde","nød"],"a":"nød","r":"'At nyde' bøjes nyder, nød, har nydt. 'I søndags' kræver datid."},
{"l":5152,"g":6,"b":4,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad er 'charme'?","o":["evnen til at få andre til at kunne lide en","evnen til at tale højt og tydeligt foran mange","evnen til at se pæn ud i dyrt tøj","evnen til at være klogere end de fleste"],"a":"evnen til at få andre til at kunne lide en","r":"En person med charme er behagelig at være sammen med og vinder let andre for sig."},
{"l":5174,"g":6,"b":4,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Hvad er rigtigt? 'I dag ___ Emil sit projekt for klassen.'","o":["præsentere","præsenterer","præsenteret","præsentrerer"],"a":"præsenterer","r":"'I dag' viser, at det er nutid, så ordet ender på -erer."},
{"l":5196,"g":6,"b":4,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Da vi fik GPS i bilen, blev turen til sommerhuset 20 minutter kortere. Far er glad og taler om tiden. Han taler ikke om den lille vej med ismejeriet, som vi altid kørte forkert ad. Vi kommer stadig frem, men nu er der ingen, der kigger ud ad vinduet.' Hvad vil skribenten have læseren til at tænke på?","o":["At familien burde købe en bedre GPS til bilen","At far burde lære at køre efter et kort igen","At man også kan miste noget, når alt går hurtigere","At det er dumt at køre forkert, når man har travlt"],"a":"At man også kan miste noget, når alt går hurtigere","r":"Turen er blevet kortere, men ismejeriet og udsigten er væk. Det er det, far ikke taler om, og som skribenten vil pege på."},
{"l":5212,"g":6,"b":4,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Træneren 'holder kortene tæt til kroppen' før finalen. Hvad betyder det?","o":["han spiller kort med sine spillere","han er sikker på at vinde kampen","han har mistet alle sine papirer","han holder sine planer hemmelige"],"a":"han holder sine planer hemmelige","r":"I kortspil skjuler man sine kort for de andre. Udtrykket bruges om at holde sine hensigter for sig selv."},
{"l":5234,"g":6,"b":4,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilken sætning om babyen består kun af grundled og udsagnsled?","o":["Babyen sover.","Babyen drikker mælk.","Babyen ligger i sengen.","Babyen gav mig et smil."],"a":"Babyen sover.","r":"'Babyen' er grundled, og 'sover' er udsagnsled. De andre sætninger har flere led."},
{"l":5256,"g":6,"b":4,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilken ordklasse har det sidste 'der' i: 'Drengen, der står der, er min bror.'","o":["stedord","biord","bindeord","forholdsord"],"a":"biord","r":"Det sidste 'der' fortæller, hvor drengen står, og er et biord. Det første 'der' indleder ledsætningen."},
{"l":5272,"g":6,"b":4,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"I hvilken sætning betyder 'lige' det samme som 'ens for alle'?","o":["Vejen går lige ud efter broen.","Hun er lige kommet hjem fra skole.","Alle borgere har lige rettigheder.","Vent, jeg skal lige finde min jakke."],"a":"Alle borgere har lige rettigheder.","r":"'Lige' kan betyde ens, ikke skæv, for et øjeblik siden og et øjeblik. Her er det rettighederne, der er ens."},
{"l":5294,"g":6,"b":4,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Hun tjekker elevernes højde og vægt på skolen. Hvilket ord er stavet rigtigt?","o":["sundhedplejerske","sunhedsplejerske","sundhesplejerske","sundhedsplejerske"],"a":"sundhedsplejerske","r":"Ordet har d både i 'sund' og i '-hed' og fuge-s foran 'plejerske'."},
{"l":5300,"g":6,"b":4,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Træneren står ved bussen, da en forælder spørger: Hvorfor er holdet stadig så dårligt, selv om det har fået ny træner?' Hvad tager forælderen for givet?","o":["At holdet er dårligt","At bussen er forsinket","At den nye træner er dårlig","At holdet har tabt sin sidste kamp"],"a":"At holdet er dårligt","r":"Spørgsmålet stiller ikke holdets niveau til diskussion. Det spørger kun hvorfor og forudsætter dermed, at holdet er dårligt."},
{"l":5318,"g":6,"b":4,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Vælg rigtigt: 'Vi havde en ___ dag på stranden.'","o":["hvidunderlig","vidunderlig","vidundelig","viddunderlig"],"a":"vidunderlig","r":"Ordet har ikke noget h foran v, og det slutter på -derlig med r."},
{"l":5342,"g":6,"b":4,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Hvad skal der stå? 'Hun er ___ gået hjem, for hendes jakke er væk.'","o":["åbenbard","obenbart","åbenbart","åbenbat"],"a":"åbenbart","r":"Ordet staves med å og ender på -bart."},
{"l":5362,"g":6,"b":4,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Clara var sur på dommeren og gav ham 'den kolde skulder'. Hvad gjorde hun?","o":["hun bad ham tage varmere tøj på","hun gav ham massage på ryggen","hun stod frem og forsvarede ham","hun lod, som om han ikke var der"],"a":"hun lod, som om han ikke var der","r":"At give nogen den kolde skulder er at behandle dem køligt og vende ryggen til dem."},
{"l":5378,"g":6,"b":4,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Hvad er stavet rigtigt? 'Kagen var ___ den bedste, jeg har smagt.'","o":["simpelthen","simpelten","simpeltden","simplethen"],"a":"simpelthen","r":"Ordet er sammensat af 'simpelt' og 'hen', så t og h står sammen."},
{"l":5400,"g":6,"b":4,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Arrangøren 'tog forbehold' for vejret. Hvad betyder det?","o":["at arrangøren allerede kender vejret flere måneder frem","at planen kan ændre sig, hvis vejret bliver dårligt","at festen holdes, uanset hvordan vejret bliver","at alle gæster selv skal medbringe en paraply"],"a":"at planen kan ændre sig, hvis vejret bliver dårligt","r":"Et forbehold er en betingelse. Man siger, at noget gælder, medmindre der sker noget bestemt."},
{"l":5415,"g":6,"b":4,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad vil det sige at 'resignere'?","o":["at blive vred og tage kampen op","at skrive sit navn under en aftale","at opgive og affinde sig med tingene","at gentage noget for at huske det"],"a":"at opgive og affinde sig med tingene","r":"Den, der resignerer, holder op med at kæmpe imod og accepterer, at tingene er, som de er."},
{"l":5438,"g":6,"b":5,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Hvad er stavet rigtigt? 'Efter tre års studier skal hun op til en stor ___.'","o":["examen","eksammen","eksamn","eksamen"],"a":"eksamen","r":"På dansk skrives x-lyden ks. Der er kun ét m, fordi a'et er langt."},
{"l":5459,"g":6,"b":5,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Hvad er der tilbage af tinsoldaten til sidst i 'Den standhaftige tinsoldat'?","o":["et lille hjerte af tin","en rusten knap af tin","en lille sko af tin","et lille sværd af tin"],"a":"et lille hjerte af tin","r":"Soldaten smelter i kakkelovnen, og tilbage ligger et lille tinhjerte. Det viser, at hans kærlighed varede ved."},
{"l":5476,"g":6,"b":5,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilken ordklasse har 'før' i: 'Før var her skov.'","o":["bindeord","biord","forholdsord","stedord"],"a":"biord","r":"'Før' står her alene og betyder 'tidligere'. Så er det et biord."},
{"l":5498,"g":6,"b":5,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilken ordklasse har 'før' i: 'Vask hænder, før du spiser.'","o":["forholdsord","biord","bindeord","stedord"],"a":"bindeord","r":"'Før' indleder her ledsætningen 'før du spiser', så det er et bindeord."},
{"l":5513,"g":6,"b":5,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad er noget, der er 'underforstået'?","o":["noget, der er skrevet med småt under en tegning","noget, der slet ikke er til at forstå","noget, der bliver sagt meget tydeligt","noget, man forstår, uden at det bliver sagt"],"a":"noget, man forstår, uden at det bliver sagt","r":"Noget underforstået ligger under ordene. Alle ved, hvad der menes, selv om det ikke siges direkte."},
{"l":5534,"g":6,"b":5,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Hvad er stavet rigtigt? 'Delfiner er kendt for deres høje ___.'","o":["intelligens","inteligens","intelligents","intelligence"],"a":"intelligens","r":"Ordet har dobbelt l og ender på -ens på dansk."},
{"l":5555,"g":6,"b":5,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Hvad er forskellen på Ole Lukøjes to paraplyer i H.C. Andersens eventyr?","o":["Den ene giver sol, den anden giver regn","Den ene giver drømme, den anden ingen drømme","Den ene er til ham, den anden til hans bror","Den ene er til søndag, den anden til hverdag"],"a":"Den ene giver drømme, den anden ingen drømme","r":"Den ene paraply har billeder og giver søde drømme. Under den anden sover man uden at drømme noget."},
{"l":5575,"g":6,"b":5,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Cyklen var Jonathans. Hvilket ord passer: 'Sanne gav Jonathan ___ gamle cykel tilbage.'","o":["sin","hendes","hans","deres"],"a":"hans","r":"Cyklen tilhører ikke grundleddet Sanne, men hensynsleddet Jonathan. Så kan der ikke stå 'sin'."},
{"l":5596,"g":6,"b":5,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad er en 'bjørnetjeneste'?","o":["en stor og venlig hjælp til nogen","en meget farlig opgave i naturen","en tjeneste, man får godt betalt for","en hjælp, der gør mere skade end gavn"],"a":"en hjælp, der gør mere skade end gavn","r":"Mange tror, at ordet betyder en stor tjeneste, men det er det modsatte: Hjælpen ender med at skade."},
{"l":5612,"g":6,"b":5,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'I H.C. Andersens eventyr Kejserens nye klæder får to snydere kejseren til at tro, at de har syet ham tøj, som dumme folk ikke kan se. Alle voksne roser det fine tøj, selvom de ikke kan se noget. Kun et lille barn siger højt, at kejseren ikke har noget på.' Hvorfor tør barnet sige det, de voksne ikke tør?","o":["Barnet tænker ikke på, om det ser dumt ud","Barnet har bedre øjne end de voksne","Barnet vil gerne drille kejseren foran alle","Barnet har hørt det af de to snydere"],"a":"Barnet tænker ikke på, om det ser dumt ud","r":"De voksne roser tøjet, fordi de ikke vil se dumme ud. Barnet siger bare det, det ser."},
{"l":5632,"g":6,"b":5,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Der findes to måder at fortælle om en dårlig kamp. Den ene: Vi blev slået med 7-1. Den anden: Vi scorede mod ligaens stærkeste hold. Begge sætninger er sande. Men hvis du er træner, og du vil have, at holdet møder op til næste træning, ved du, hvilken du skal vælge.' Hvad viser eksemplet med de to sætninger?","o":["At en træner godt må lyve for sit hold","At to sande sætninger kan virke helt forskelligt","At den første sætning er sand, og den anden løgn","At resultater aldrig bør nævnes efter en kamp"],"a":"At to sande sætninger kan virke helt forskelligt","r":"Begge sætninger er sande, men har forskellig virkning. Afsenderen vælger ud fra, hvad han vil opnå."},
{"l":5652,"g":6,"b":5,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Vælg den rigtige form af 'at smage': 'Den kage ville jeg gerne have ___.'","o":["smagte","smager","smagt","smage"],"a":"smagt","r":"Efter 'have' står tillægsformen, ligesom efter 'har': jeg har smagt, jeg ville have smagt."},
{"l":5674,"g":6,"b":5,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Vælg datid af 'at fare': 'I sidste uge ___ vi vild i skoven.'","o":["faret","farer","fare","for"],"a":"for","r":"Datid af 'at fare' er 'for'. Her er 'for' altså et udsagnsord og ikke et forholdsord."},
{"l":5693,"g":6,"b":5,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad betyder det, at en dom 'skaber præcedens'?","o":["at den fremover gælder som eksempel i lignende sager","at den straks bliver ændret af en højere domstol","at den skal holdes hemmelig for offentligheden","at den er den hårdeste straf, der nogensinde er givet"],"a":"at den fremover gælder som eksempel i lignende sager","r":"En præcedens er en tidligere afgørelse, som domstole kan støtte sig til i senere sager af samme slags."},
{"l":5716,"g":7,"b":1,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvad er grundleddet (subjektet) i sætningen: 'I morgen skal Aisha og hendes hold spille håndbold mod Viborg.'?","o":["Aisha","Aisha og hendes hold","I morgen","håndbold mod Viborg"],"a":"Aisha og hendes hold","r":"Spørg: Hvem skal spille? Det er både Aisha og hendes hold, så hele leddet er grundled. Det står efter udsagnsordet, fordi sætningen begynder med 'I morgen'."},
{"l":5733,"g":7,"b":1,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Læs: '– Jeg kommer nu, råbte Karl og løb ned ad trappen. Hans mor rystede på hovedet.' Hvilken type fortæller har teksten?","o":["jeg-fortæller","du-fortæller","han-fortæller","vi-fortæller"],"a":"han-fortæller","r":"'Jeg' står kun i det, Karl siger. Fortælleren selv kalder ham 'Karl' og 'hans', så det er en han-fortæller, også kaldet tredjepersonsfortæller."},
{"l":5753,"g":7,"b":1,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvem er 'målgruppen' for en reklame?","o":["de mennesker, der har lavet reklamen","de mennesker, der optræder i reklamen","de mennesker, der har betalt for reklamen","de mennesker, reklamen skal nå ud til"],"a":"de mennesker, reklamen skal nå ud til","r":"Målgruppen er dem, afsenderen sigter efter. En reklame for legetøj har for eksempel børn og forældre som målgruppe."},
{"l":5772,"g":7,"b":1,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Vælg stavemåden: 'Er dit svar ___, får du et point.'","o":["korrekt","korekt","korrect","korrækt"],"a":"korrekt","r":"Ordet har dobbelt-r og ender på -kt. Engelsk 'correct' med c må ikke forveksles med det."},
{"l":5798,"g":7,"b":1,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Grønne planter bruger 'fotosyntese'. Hvad sker der i den proces?","o":["planten danner nye frø efter bestøvning af bier","planten laver sukker og ilt ved hjælp af sollys","planten suger vand op gennem rødderne","planten mister sine blade om efteråret"],"a":"planten laver sukker og ilt ved hjælp af sollys","r":"'Foto' betyder lys, og 'syntese' betyder sammensætning. Planten bruger lysets energi til at bygge sukker af vand og kuldioxid."},
{"l":5813,"g":7,"b":1,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Danmark køber varer fra udlandet. Det kaldes 'import'. Hvad kaldes det modsatte, altså når vi sælger varer til andre lande?","o":["transport","rapport","eksport","support"],"a":"eksport","r":"Forstavelsen 'im-' betyder ind, og 'eks-' betyder ud. Varer, der går ud af landet, er eksport."},
{"l":5835,"g":7,"b":1,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Læs: 'Elever, der spiser morgenmad, klarer sig bedre i skolen. Start dagen med en skål Sprødmüsli!' Hvad er tekstens vigtigste formål?","o":["At fortælle om en ny undersøgelse af elever","At forklare, hvorfor morgenmad er sundt","At give eleverne gode råd om skolen","At få læseren til at købe müslien"],"a":"At få læseren til at købe müslien","r":"Første sætning ligner en oplysning, men den skal bare give en grund til at købe. Teksten slutter med at opfordre læseren til at vælge varen, og det er reklamens formål."},
{"l":5851,"g":7,"b":1,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvilket navneord er dannet af tillægsordet 'fattig'?","o":["fattigdom","fattigt","fattigere","fattigste"],"a":"fattigdom","r":"Endelsen -dom gør tillægsordet til et navneord, ligesom i 'sygdom'. De andre svar er bøjninger af selve tillægsordet."},
{"l":5870,"g":7,"b":1,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Nogle siger, at man ikke behøver at lære noder, når man kan spille efter gehør. Det er rigtigt, at mange gode musikere startede sådan. Men man kunne lige så godt sige, at børn ikke behøver bogstaver, fordi de kan tale.' Hvorfor nævner skribenten bogstaverne?","o":["For at vise, at gehør er lige så naturligt for børn som at tale","For at vise, at noder er værd at lære, ligesom bogstaver er det","For at vise, at noder er sværere at lære end bogstaverne","For at vise, at musik og læsning bør læres samme år i skolen"],"a":"For at vise, at noder er værd at lære, ligesom bogstaver er det","r":"Ingen ville sige, at børn kan undvære bogstaver, bare fordi de kan tale. På samme måde mener skribenten, at man ikke kan undvære noder, bare fordi man kan spille efter gehør."},
{"l":5892,"g":7,"b":1,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilket stedord skal stå: 'Sofie og ___ var de første, der kom.'?","o":["mig","mit","jeg","os"],"a":"jeg","r":"Sofie og stedordet er sammen grundled, så der skal stå 'jeg'. Prøv at fjerne Sofie: 'Jeg var den første', ikke 'Mig var den første'."},
{"l":5911,"g":7,"b":1,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad mener man med at 'smede, mens jernet er varmt'?","o":["at arbejde hårdt fra morgen til aften","at blive vred, mens man arbejder","at lave noget om, der er mislykket","at handle, mens chancen er der"],"a":"at handle, mens chancen er der","r":"En smed kan kun forme jernet, mens det er varmt. Derfor betyder talemåden, at man skal gribe en chance, før den er væk."},
{"l":5928,"g":7,"b":1,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Hvad mangler? 'Min bror kan ikke lide oliven, og det kan jeg ___ ikke.'","o":["heller","hellere","heler","helle"],"a":"heller","r":"'Heller ikke' betyder, at det samme gælder for mig. Der er ingen sammenligning her, så der skal ikke -e på."},
{"l":5954,"g":7,"b":1,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Hvilket ord er rigtigt? 'Hun blev så ___, da hunden gøede, at hun tabte sin is.'","o":["forskræket","forskrækket","forskrækked","forskrækt"],"a":"forskrækket","r":"Ordet har dobbelt-k og ender på -et, selvom det lyder som -ed."},
{"l":5971,"g":7,"b":1,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"'Ministeren fik skarp kritik.' Hvad betyder 'skarp' her?","o":["spids","venlig","hård","lysende"],"a":"hård","r":"Her er 'skarp' brugt i overført betydning om kritik, der rammer hårdt. En kniv er derimod skarp i bogstavelig forstand."},
{"l":5991,"g":7,"b":1,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Tabellen viser længden af tre gåture. Ruten om søen er 5 km og tager 70 minutter. Skovruten er 4 km og tager 75 minutter. Byruten er 6 km og tager 80 minutter.' Hvilken slutning kan man drage af tabellen?","o":["Byruten er den rute, der tager kortest tid","Søruten er længst, målt i kilometer","Skovruten tager kortest tid, fordi den er kortest","Skovruten er langsommest at gå pr. kilometer"],"a":"Skovruten er langsommest at gå pr. kilometer","r":"Skovruten kræver næsten 19 minutter pr. kilometer, de to andre 14 og 13,3. Den er kortest i kilometer, men ikke i tid."},
{"l":6002,"g":7,"b":2,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Nogle siger, at ordblinde elever snyder, når de får bøgerne læst op. Men ingen ville sige, at en elev med briller snyder, fordi glassene hjælper med at se.' Hvad er skribentens pointe?","o":["Oplæsning er et hjælpemiddel, ikke snyd","Alle elever burde bruge briller i timerne","Ordblinde elever ser dårligere end andre","Elever med briller får også for meget hjælp"],"a":"Oplæsning er et hjælpemiddel, ikke snyd","r":"Briller hjælper en elev med at se, og det er ikke snyd. På samme måde hjælper oplæsning ordblinde elever med at læse. Teksten handler altså ikke om syn."},
{"l":6022,"g":7,"b":2,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Læs: 'Emil sprang op og gav sin plads i bussen til en gammel dame.' Hvordan karakteriseres Emil her?","o":["Direkte, med fortællerens ord","Indirekte, gennem det han gør","Gennem en lang miljøbeskrivelse","Gennem det andre siger om ham"],"a":"Indirekte, gennem det han gør","r":"Fortælleren siger ikke, at Emil er hensynsfuld. Vi slutter det selv ud fra hans handling, og det er indirekte karakteristik."},
{"l":6045,"g":7,"b":2,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Hvad er det rigtige ord? 'Vi har aldrig ___ turen til Bornholm.'","o":["fortrydt","fortrudet","fortrudt","fortrut"],"a":"fortrudt","r":"Tillægsformen af 'fortryde' skifter y til u og ender på -dt."},
{"l":6061,"g":7,"b":2,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"'Nu må Oliver tage skeen i den anden hånd.' Hvad betyder det?","o":["han må lære at spise pænt ved bordet","han må bede andre om hjælp til arbejdet","han må holde helt op med det, han laver","han må tage sig sammen og gøre det bedre"],"a":"han må tage sig sammen og gøre det bedre","r":"Talemåden bruges, når nogen skal ændre en dårlig vane eller indsats. Den har intet at gøre med bordskik."},
{"l":6083,"g":7,"b":2,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvilket navneord er dannet af tillægsordet 'afhængig'?","o":["afhængighed","afhængigt","afhænge","afhængige"],"a":"afhængighed","r":"Endelsen -hed laver mange tillægsord om til navneord. 'Afhænge' er et udsagnsord, og de to andre er bøjninger af tillægsordet."},
{"l":6100,"g":7,"b":2,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Som sygeplejerske gennem 25 år har jeg set, hvad søvnmangel gør ved unge mennesker. Derfor beder jeg skolerne om at flytte første time til klokken ni.' Hvordan søger skribenten at gøre sit krav troværdigt?","o":["Ved at fremlægge målinger fra skolernes elever","Ved at henvise til sin lange erfaring i faget","Ved at forklare, hvor meget søvn unge skal have","Ved at fortælle, hvad unge selv siger om søvn"],"a":"Ved at henvise til sin lange erfaring i faget","r":"Skribenten bruger sit arbejde som bevis på, at hun ved noget om emnet. Det kaldes etos."},
{"l":6120,"g":7,"b":2,"role":"challenge","insight":"reframing","k":"t","variant":"authored","q":"Efter hvilket ord kræves der komma: 'Læreren spurgte om vi havde læst kapitlet men ingen svarede.'?","o":["vi","læst","kapitlet","ingen"],"a":"kapitlet","r":"Ledsætningen slutter efter 'kapitlet', og foran 'men' skal der være komma mellem de to sætninger."},
{"l":6137,"g":7,"b":2,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilket ord skal stå i skriftsprog: 'Jeg har ikke ___ cykel lige nu.'?","o":["nogle","noget","mange","nogen"],"a":"nogen","r":"'Cykel' står i ental og er et fælleskønsord, så det hedder 'nogen'. 'Nogle' er kun flertal, og 'noget' passer til intetkøn."},
{"l":6158,"g":7,"b":2,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Pindsvin går i 'dvale' om vinteren. Hvad betyder det?","o":["de sover dybt og bruger næsten ingen energi","de vandrer til varmere egne om efteråret","de spiser mere end normalt hele vinteren","de skifter farve på pelsen"],"a":"de sover dybt og bruger næsten ingen energi","r":"I dvale falder kropstemperatur og puls, så dyret bruger meget lidt energi i den kolde tid uden føde."},
{"l":6180,"g":7,"b":2,"role":"challenge","insight":"reframing","k":"t","variant":"authored","q":"Hvordan deler man ordet 'arbejdsdag' rigtigt ved linjeskift?","o":["arbejd-sdag","arbejds-dag","arbejdsd-ag","arbej-dsdag"],"a":"arbejds-dag","r":"Sammensatte ord deles mellem de to ord, de er bygget af, og fuge-s'et hører til første led: arbejds-dag."},
{"l":6200,"g":7,"b":2,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Jeg forstår ikke, at folk klager over støjen fra byfesten. Den varer kun tre dage, og selv mærker jeg intet til den, for jeg bor 30 kilometer væk.' Hvad svækker skribentens argument?","o":["Skribenten oplyser ikke, hvor mange dage byfesten varer","Skribenten bor i samme by som dem, der har klaget","Skribenten bor for langt væk til selv at høre støjen","Skribenten tager ikke stilling til, om der er støj"],"a":"Skribenten bor for langt væk til selv at høre støjen","r":"Skribenten siger, at støjen ikke er slem, men bor 30 kilometer væk og hører den slet ikke. Så kan man ikke vide, hvor slem den er."},
{"l":6211,"g":7,"b":2,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Da jeg var ti, ville jeg være astronaut. Da jeg var tolv, ville jeg være dyrlæge. Nu er jeg 14 og vil bare gerne igennem torsdag.' Hvad får den sidste sætning til at virke sjov?","o":["Fortælleren er blevet klogere på rummet med alderen","Fortælleren vil nu være noget helt andet end dyrlæge","Vi får at vide, hvad der skal ske om torsdagen","De store drømme er blevet til bare at nå igennem torsdag"],"a":"De store drømme er blevet til bare at nå igennem torsdag","r":"Først vil fortælleren være astronaut og dyrlæge, og nu er målet bare at komme igennem en torsdag. Det er sjovt, fordi springet fra det store til det lille er så stort."},
{"l":6233,"g":7,"b":2,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Mor siger altid, at det ikke er farligt at tabe. Hun sagde det også, da vi kørte hjem fra stævnet, og hun sagde det to gange, med blikket stift på vejen.' Hvad antyder sidste del af teksten?","o":["At moren selv har svært ved at tabe","At moren er bange for at køre galt i bilen","At moren ikke hørte, at barnet havde tabt","At moren har glemt, at hun allerede har sagt det"],"a":"At moren selv har svært ved at tabe","r":"Hun siger det to gange og kigger stift på vejen. Det passer dårligt til de rolige ord, så man kan mærke, at hun ikke selv tror helt på det."},
{"l":6253,"g":7,"b":2,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Hvilket ord mangler? 'Klassen fik 7 i ___ til prøven.'","o":["genemsnit","gennemsnit","gennemsnidt","gennemsnitt"],"a":"gennemsnit","r":"Ordet består af 'gennem' og 'snit'. Der er dobbelt-n i 'gennem' og kun ét t til sidst."},
{"l":6277,"g":7,"b":2,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Læs: 'Mens Anna troede, at Lars var sur, tænkte Lars kun på sin syge hund, og ingen af dem anede, hvad morgendagen ville bringe.' Hvilken fortæller er det?","o":["begrænset fortæller","jeg-fortæller","alvidende fortæller","du-fortæller"],"a":"alvidende fortæller","r":"Fortælleren kender flere personers tanker og også fremtiden. Så meget ved kun en alvidende fortæller."},
{"l":6299,"g":7,"b":3,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Man siger, at unge ikke læser længere. Men hvad kalder man så de timer, vi bruger på opslag, beskeder og lange tråde?' Hvad vil skribenten sige med spørgsmålet?","o":["At opslag er vigtigere end bøger","At unge burde læse langt færre beskeder","At voksne ikke kan forstå unges beskeder","At unge læser meget, bare på en anden måde"],"a":"At unge læser meget, bare på en anden måde","r":"Det er et retorisk spørgsmål, altså et, hvor svaret er givet: Det kaldes også læsning. Skribenten siger intet om, hvad der er vigtigst."},
{"l":6305,"g":7,"b":3,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Hvad er rigtigt her? 'Han kom for sent og havde ingen god ___.'","o":["undskyldning","unskyldning","undskylning","unskylning"],"a":"undskyldning","r":"Ordet indeholder 'skyld', og begge d'er skal med, selvom de ikke høres."},
{"l":6323,"g":7,"b":3,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad sker der, når vanddamp 'kondenserer' på et koldt vindue?","o":["den trækker ud gennem ruden","den bliver til små dråber","den stiger op mod loftet","den bliver til et lag af sne"],"a":"den bliver til små dråber","r":"Når vanddampen bliver afkølet, går den fra gas til væske. Derfor dugger ruden."},
{"l":6345,"g":7,"b":3,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Hvilket af disse eventyr er et kunsteventyr, som en navngiven forfatter selv har fundet på?","o":["Rødhætte","Hans og Grete","Den lille havfrue","Snehvide"],"a":"Den lille havfrue","r":"'Den lille havfrue' er H.C. Andersens eget værk. De andre er folkeeventyr, som brødrene Grimm samlede."},
{"l":6367,"g":7,"b":3,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvad angiver ledsætningen i: 'Regner det, bliver vi hjemme.'?","o":["tid","årsag","indrømmelse","betingelse"],"a":"betingelse","r":"Ledsætningen har ikke noget bindeord, men den betyder det samme som 'hvis det regner'. Vi bliver kun hjemme på den betingelse."},
{"l":6389,"g":7,"b":3,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvad angiver ledsætningen i: 'Selvom Tobias var træt, løb han videre.'?","o":["indrømmelse","årsag","betingelse","tid"],"a":"indrømmelse","r":"'Selvom' viser, at noget sker på trods af noget andet. Det kaldes en indrømmelse."},
{"l":6409,"g":7,"b":3,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Hvad er rigtigt? 'Hans skrift var så ___, at ingen kunne læse den.'","o":["sjussket","sjusket","sjusked","sjuskket"],"a":"sjusket","r":"Ordet begynder med sj og ender på -et, selvom det lyder som d."},
{"l":6428,"g":7,"b":3,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad er en 'ideologi'?","o":["en samling regler for god opførsel ved bordet","en liste over idéer til nye opfindelser","en samling idéer om, hvordan samfundet bør indrettes","en beskrivelse af, hvordan landenes grænser er opstået"],"a":"en samling idéer om, hvordan samfundet bør indrettes","r":"En ideologi er en sammenhængende måde at se verden og samfundet på. Politiske partier bygger ofte på en ideologi."},
{"l":6447,"g":7,"b":3,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Læs: 'Det var jo en strålende idé at glemme madpakken, sagde Mette til sig selv og gned sin tomme mave.' Hvad mener Mette egentlig?","o":["At hun er glad for at slippe for madpakken","At hun har fået en god idé til en ny madpakke","At hun synes, at madpakker er noget skidt","At hun ærgrer sig over at have glemt den"],"a":"At hun ærgrer sig over at have glemt den","r":"Mette bruger ironi: Ordet 'strålende' betyder det modsatte, og den tomme mave viser, at hun ærgrer sig."},
{"l":6466,"g":7,"b":3,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"I et brev står der: 'Du vil blive underrettet pr. brev.' Hvad betyder det?","o":["du får besked med posten","du får en bøde med posten","du skal selv skrive et brev","du får dine fejl rettet med posten"],"a":"du får besked med posten","r":"At underrette nogen er at give dem besked. Ordet har intet at gøre med at rette fejl."},
{"l":6488,"g":7,"b":3,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Kommunen bliver beskyldt for at 'sylte' en sag. Hvad betyder det?","o":["at afgøre sagen meget hurtigt","at lade sagen ligge uden at behandle den","at offentliggøre hele sagen i aviserne","at gøre sagen mere indviklet"],"a":"at lade sagen ligge uden at behandle den","r":"Billedet er syltetøj, der står gemt på hylden i lang tid. En syltet sag ligger stille, så der ikke sker noget med den."},
{"l":6500,"g":7,"b":3,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Regel A: Ingen elev må forlade skolen i frikvarteret. Regel B: Elever må ikke forlade skolen i frikvarteret uden tilladelse.' Hvad er den afgørende forskel?","o":["A gælder for færre elever end regel B","B gælder kun i store frikvarterer","Efter B kan man få lov, efter A kan man ikke","A giver lærerne ret til at give tilladelse"],"a":"Efter B kan man få lov, efter A kan man ikke","r":"'Uden tilladelse' gør, at man kan få lov. A gælder altid. Sådan kan to små ord ændre hele reglen."},
{"l":6520,"g":7,"b":3,"role":"challenge","insight":"reframing","k":"t","variant":"authored","q":"Hvilken skrivemåde er rigtig: 'Emma fik et ___ i sin danskstil.'? Det er topkarakteren.","o":["12 tal","12tal","12'tal","12-tal"],"a":"12-tal","r":"Når et tal sættes sammen med et ord, bruger man bindestreg."},
{"l":6541,"g":7,"b":3,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvilket navneord hører til udsagnsordet 'analysere'?","o":["analyse","analyserer","analytisk","analyseret"],"a":"analyse","r":"Her kommer navneordet ved at fjerne endelsen -re. 'Analytisk' er et tillægsord, og de to andre er bøjninger af udsagnsordet."},
{"l":6563,"g":7,"b":3,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"'Forslaget faldt igennem ved afstemningen.' Hvad skete der med forslaget?","o":["det blev vedtaget","det blev afvist","det blev udskudt","det blev ændret"],"a":"det blev afvist","r":"Når noget falder igennem, er der ikke opbakning nok til det. Forslaget fik ikke flertal."}
]$$::jsonb) AS e
JOIN (VALUES
  ('s', 'stavning', 'recall', 'factual', 'surface_association'),
  ('o', 'ordforråd', 'recall', 'factual', 'surface_association'),
  ('g', 'grammatik', 'application', 'applied', 'overgeneralization'),
  ('t', 'tegnsætning', 'application', 'applied', 'overgeneralization'),
  ('l', 'læseforståelse', 'comprehension', 'conceptual', 'surface_association'),
  ('f', 'litteratur', 'analysis', 'inferential', 'surface_association')
) AS m(k, concept, skill, dtype, mis) ON m.k = e->>'k';
